use std::io::{self, BufRead, Write};

enum Node {
    Lit(i64),
    Neg(Box<Node>),
    Bin(char, Box<Node>, Box<Node>),
}

impl Node {
    fn eval(&self) -> i64 {
        match self {
            Node::Lit(v) => *v,
            Node::Neg(a) => a.eval().wrapping_neg(),
            Node::Bin(op, a, b) => {
                let (x, y) = (a.eval(), b.eval());
                match op {
                    '+' => x.wrapping_add(y),
                    '-' => x.wrapping_sub(y),
                    _ => x.wrapping_mul(y),
                }
            }
        }
    }

    fn depth(&self) -> usize {
        match self {
            Node::Lit(_) => 1,
            Node::Neg(a) => 1 + a.depth(),
            Node::Bin(_, a, b) => 1 + a.depth().max(b.depth()),
        }
    }

    fn count(&self) -> usize {
        match self {
            Node::Lit(_) => 1,
            Node::Neg(a) => 1 + a.count(),
            Node::Bin(_, a, b) => 1 + a.count() + b.count(),
        }
    }

    fn render(&self) -> String {
        match self {
            Node::Lit(v) => v.to_string(),
            Node::Neg(a) => format!("-({})", a.render()),
            Node::Bin(op, a, b) => format!("({} {} {})", a.render(), op, b.render()),
        }
    }
}

fn parse(tokens: &[String], pos: &mut usize) -> Node {
    let tok = tokens[*pos].as_str();
    *pos += 1;
    if tok == "(" {
        let op = tokens[*pos].clone();
        *pos += 1;
        let node = if op == "neg" {
            Node::Neg(Box::new(parse(tokens, pos)))
        } else {
            let a = parse(tokens, pos);
            let b = parse(tokens, pos);
            Node::Bin(op.chars().next().unwrap(), Box::new(a), Box::new(b))
        };
        // consume closing ')'
        *pos += 1;
        node
    } else {
        Node::Lit(tok.parse().unwrap())
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let spaced = line.replace('(', " ( ").replace(')', " ) ");
        let tokens: Vec<String> = spaced.split_whitespace().map(|s| s.to_string()).collect();
        if tokens.is_empty() {
            continue;
        }
        let mut pos = 0;
        let tree = parse(&tokens, &mut pos);
        writeln!(
            out,
            "{} {} {} {}",
            tree.eval(),
            tree.depth(),
            tree.count(),
            tree.render()
        )
        .unwrap();
    }
}
